  "Impossible de charger les données : {error}": { en: "Could not load the data: {error}", de: "Daten konnten nicht geladen werden: {error}", es: "No se pudieron cargar los datos: {error}", pt: "Não foi possível carregar os dados: {error}", ru: "Не удалось загрузить данные: {error}", ko: "데이터를 불러올 수 없음: {error}", zhCN: "无法加载数据：{error}", zhTW: "無法載入資料：{error}" },
