  "Munitions à garder": { en: "Ammo to keep", de: "Vorrat an Munition", es: "Munición a mantener", pt: "Munição a manter", ru: "Запас боеприпасов", ko: "보유할 탄약", zhCN: "保留弹药数量", zhTW: "保留彈藥數量" },
  "Chasseurs : flèches ou balles selon l'arme.": { en: "Hunters: arrows or bullets depending on the weapon.", de: "Jäger: Pfeile oder Kugeln je nach Waffe.", es: "Cazadores: flechas o balas según el arma.", pt: "Caçadores: flechas ou balas conforme a arma.", ru: "Охотники: стрелы или пули в зависимости от оружия.", ko: "사냥꾼: 무기에 따라 화살 또는 탄환.", zhCN: "猎人：根据武器选择箭或子弹。", zhTW: "獵人：依武器選擇箭或子彈。" },
  "Équipement et talents": { en: "Gear and talents", de: "Ausrüstung und Talente", es: "Equipo y talentos", pt: "Equipamento e talentos", ru: "Снаряжение и таланты", ko: "장비와 특성", zhCN: "装备与天赋", zhTW: "裝備與天賦" },
